      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed atomic timekeeping and opened a new regime for precision tests of fundamental physics.",
        "attribution": "Katori and Ye independently developed central approaches and led influential experimental realizations.",
        "maturity": "The clocks have matured through repeated improvements and independent implementations, with clear scientific uses beyond time standards.",
        "uncertainties": [
          "The prize framing should distinguish the enabling clock concept from the broader international development of optical frequency standards."
        ]
      }
    },
